using System.Globalization;
using System.Text.RegularExpressions;
using UsbToC64.Core.Model;
using UsbToC64.Core.Text;

namespace UsbToC64.Core.Formats;

public enum HeaderGenerator
{
    Unknown,
    /// <summary>"Generated by Smart Web Configurator" (configurator.html, with WEB_META).</summary>
    SmartWebConfigurator,
    /// <summary>"Generated by the USBtoC64 Configurator (WebHID)" (old config.html, no WEB_META).</summary>
    LegacyWebHid,
}

/// <summary>One entry of the WEB_META line: zone:index:value:action:color.</summary>
public sealed record WebMetaEntry(string Zone, int Index, int Value, string Action, string Color);

public sealed class ImportedHeader
{
    public required JmProfile Profile { get; init; }
    public required HeaderGenerator Generator { get; init; }
    /// <summary>JM_HAS_DPAD_INDEX: in the compiled .h, rules on the D-pad byte only act as directions.</summary>
    public bool HeaderUsesDpadIndex { get; init; }
    /// <summary>JM_USE_ANALOG_MOUSE: in the compiled .h these indexes are only used in mouse mode.</summary>
    public bool HeaderAnalogMouse { get; init; }
    public IReadOnlyList<WebMetaEntry> WebMeta { get; init; } = Array.Empty<WebMetaEntry>();
    public List<string> Notes { get; } = new();
}

/// <summary>
/// Reads a JoystickMapping.h produced by either web configurator. The C rule array is the
/// source of truth (it is what the firmware compiles); WEB_META is only informative.
/// Enum names are mapped by name, because the old generator used different ordinals.
/// </summary>
public static class HeaderImporter
{
    private static readonly Dictionary<string, JmOp> Ops = new()
    {
        ["JM_EQ"] = JmOp.Eq, ["JM_BITANY"] = JmOp.BitAny, ["JM_HAT"] = JmOp.Hat,
    };

    private static readonly Dictionary<string, JmFunc> Funcs = new()
    {
        ["JM_UP"] = JmFunc.Up, ["JM_UP_RIGHT"] = JmFunc.UpRight, ["JM_RIGHT"] = JmFunc.Right,
        ["JM_RIGHT_DOWN"] = JmFunc.RightDown, ["JM_DOWN"] = JmFunc.Down, ["JM_DOWN_LEFT"] = JmFunc.DownLeft,
        ["JM_LEFT"] = JmFunc.Left, ["JM_LEFT_UP"] = JmFunc.LeftUp,
        ["JM_FIRE"] = JmFunc.Fire1, ["JM_FIRE2"] = JmFunc.Fire2, ["JM_FIRE3"] = JmFunc.Fire3,
        ["JM_AUTOFIRE_ON"] = JmFunc.AutofireOn, ["JM_AUTOFIRE_OFF"] = JmFunc.AutofireOff,
        ["JM_AUTOFIRE_HOLD"] = JmFunc.AutofireHold,
        ["JM_AUTOLEFTRIGHT_ON"] = JmFunc.AutoLeftRightOn, ["JM_AUTOLEFTRIGHT_OFF"] = JmFunc.AutoLeftRightOff,
    };

    public static ImportedHeader Import(string text)
    {
        var gen = text.Contains("Generated by Smart Web Configurator") ? HeaderGenerator.SmartWebConfigurator
                : text.Contains("Generated by the USBtoC64 Configurator") ? HeaderGenerator.LegacyWebHid
                : HeaderGenerator.Unknown;

        var p = new JmProfile
        {
            Vid = (ushort)MatchInt(text, @"//\s*Vendor ID:\s*(\d+)", 0),
            Pid = (ushort)MatchInt(text, @"//\s*Product ID:\s*(\d+)", 0),
            DeviceName = Regex.Match(text, @"//\s*Device:\s*(.+)") is { Success: true } dm ? dm.Groups[1].Value.Trim() : null,
            DpadIndex = (sbyte)MatchInt(text, @"#define\s+JM_DPAD_INDEX\s+(-?\d+)", -1),
        };

        var result = new ImportedHeader
        {
            Profile = p,
            Generator = gen,
            HeaderUsesDpadIndex = MatchInt(text, @"#define\s+JM_HAS_DPAD_INDEX\s+(\d+)", 0) == 1,
            HeaderAnalogMouse = MatchInt(text, @"#define\s+JM_USE_ANALOG_MOUSE\s+(\d+)", 0) == 1,
            WebMeta = ParseWebMeta(text),
        };

        var block = Regex.Match(text, @"JM_JOY_RULES\[\]\s*=\s*\{(.*?)\};", RegexOptions.Singleline);
        if (!block.Success)
            throw new FormatException(L.T("fmt.norules"));

        var ruleRx = new Regex(@"\{\s*(\d+)\s*,\s*(\d+)\s*,\s*(JM_\w+)\s*,\s*(JM_\w+)\s*\}");
        foreach (Match m in ruleRx.Matches(StripComments(block.Groups[1].Value)))
        {
            string opName = m.Groups[3].Value, funcName = m.Groups[4].Value;
            if (!Ops.TryGetValue(opName, out var op)) { result.Notes.Add(L.F("fmt.unknownop", opName)); continue; }
            if (!Funcs.TryGetValue(funcName, out var fn)) { result.Notes.Add(L.F("fmt.unknownfunc", funcName)); continue; }
            p.Rules.Add(new JmRule(byte.Parse(m.Groups[1].Value, CultureInfo.InvariantCulture),
                                   byte.Parse(m.Groups[2].Value, CultureInfo.InvariantCulture), op, fn));
        }

        if (result.HeaderAnalogMouse)
        {
            foreach (var b in ParseByteArray(text, "JM_MOUSE_X_INDEXES")) p.AnalogX.Add(b);
            foreach (var b in ParseByteArray(text, "JM_MOUSE_Y_INDEXES")) p.AnalogY.Add(b);
            result.Notes.Add(L.T("fmt.analog"));
        }

        if (gen == HeaderGenerator.LegacyWebHid)
            result.Notes.Add(L.T("fmt.legacy"));
        if (gen == HeaderGenerator.SmartWebConfigurator && result.WebMeta.Count == 0)
            result.Notes.Add(L.T("fmt.emptymeta"));

        return result;
    }

    private static int MatchInt(string text, string pattern, int def) =>
        Regex.Match(text, pattern) is { Success: true } m ? int.Parse(m.Groups[1].Value, CultureInfo.InvariantCulture) : def;

    private static string StripComments(string s) =>
        Regex.Replace(Regex.Replace(s, @"//[^\n]*", ""), @"/\*.*?\*/", "", RegexOptions.Singleline);

    private static IEnumerable<byte> ParseByteArray(string text, string name)
    {
        var m = Regex.Match(text, name + @"\[\]\s*=\s*\{([^}]*)\}");
        if (!m.Success) yield break;
        foreach (var part in m.Groups[1].Value.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
            if (byte.TryParse(part, NumberStyles.Integer, CultureInfo.InvariantCulture, out var b)) yield return b;
    }

    private static List<WebMetaEntry> ParseWebMeta(string text)
    {
        var list = new List<WebMetaEntry>();
        var m = Regex.Match(text, @"//\s*WEB_META:[ \t]*([^\r\n]*)");
        if (!m.Success) return list;
        foreach (var item in m.Groups[1].Value.Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            var parts = item.Split(':');
            if (parts.Length < 5) continue;
            if (!int.TryParse(parts[1], out var idx) || !int.TryParse(parts[2], out var val)) continue;
            list.Add(new WebMetaEntry(parts[0], idx, val, parts[3], parts[4]));
        }
        return list;
    }
}
